#!/usr/bin/env node
'use strict';
// Packs the site's content files (site text, devotional days, journal posts and the
// monogram SVGs) into lib/bundle.js, because Cloudflare Workers have no file system.
// Run after editing anything in content/ or the monogram SVGs:  npm run bundle
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const rd = (...p) => fs.readFileSync(path.join(root, ...p), 'utf8');
const journalDir = path.join(root, 'content', 'journal');
const out = {
  site: JSON.parse(rd('content', 'site-content.json')),
  days: JSON.parse(rd('content', 'days.json')),
  journal: fs.readdirSync(journalDir).filter(f => f.endsWith('.md')).sort().map(f => ({ file: f, raw: rd('content', 'journal', f) })),
  studies: JSON.parse(rd('content', 'studies.json')),
  svg: { monogram: rd('public', 'assets', 'monogram.svg'), monogramBold: rd('public', 'assets', 'monogram-bold.svg') },
};
fs.writeFileSync(path.join(root, 'lib', 'bundle.js'), "'use strict';\n// GENERATED by scripts/build-bundle.js. Do not edit by hand: edit content/ and run `npm run bundle`.\nmodule.exports = " + JSON.stringify(out) + ';\n');
console.log('lib/bundle.js written (' + out.journal.length + ' journal posts, ' + out.days.length + ' days)');
